#include "window.h"
#include <QtWidgets>
#include <QSettings>
void Window::spectrumOptions(){
 QDialog dialog(this);dialog.setObjectName("spectrumSettingsDialog");dialog.setWindowTitle("Spectre / Waterfall — échelle et affichage");auto form=new QFormLayout(&dialog);auto mode=new QComboBox;mode->setObjectName("spectrumScaleMode");mode->addItem("Échelle fixe — −20 à −100 dBFS",false);mode->addItem("Échelle automatique — facultative",true);mode->setCurrentIndex(spectrum_->automaticScale?1:0);form->addRow("Échelle verticale",mode);
 auto fixed=new QLabel("Maximum : −20 dBFS   •   Minimum : −100 dBFS");fixed->setObjectName("spectrumFixedBounds");fixed->setWordWrap(true);form->addRow(fixed);auto palette=new QLabel("Bleu professionnel : bleu nuit → bleu azur → cyan glacé");palette->setWordWrap(true);form->addRow("Palette waterfall",palette);
 auto contrast=new QDoubleSpinBox;contrast->setObjectName("spectrumContrast");contrast->setRange(.25,4);contrast->setDecimals(2);contrast->setSingleStep(.1);contrast->setValue(spectrum_->contrast);form->addRow("Contraste waterfall",contrast);
 auto brightness=new QSpinBox;brightness->setObjectName("spectrumBrightness");brightness->setRange(-100,100);brightness->setSuffix(" %");brightness->setSingleStep(5);brightness->setValue(qRound(spectrum_->brightness*100));form->addRow("Luminosité waterfall",brightness);
 auto smoothing=new QSpinBox;smoothing->setObjectName("spectrumSmoothing");smoothing->setRange(1,30);smoothing->setValue(spectrum_->smoothingFrames);smoothing->setSpecialValueText("Désactivé (1 trame)");smoothing->setSuffix(" trames");smoothing->setToolTip("Moyenne exponentielle de la puissance FFT : coefficient 1/N. Ne modifie ni les mesures brutes ni le waterfall.");form->addRow("Lissage de la courbe",smoothing);
 auto speed=new QSpinBox;speed->setObjectName("spectrumWaterfallStride");speed->setRange(1,30);speed->setValue(spectrum_->waterfallStride);form->addRow("Une ligne waterfall / N trames",speed);
 auto note=new QLabel("La courbe cyan et le waterfall utilisent les véritables mesures FFT. Contraste et luminosité changent uniquement les couleurs. Les réglages sont appliqués et enregistrés immédiatement.");note->setWordWrap(true);note->setMaximumWidth(540);form->addRow(note);
 auto apply=[&,this]{spectrum_->automaticScale=mode->currentData().toBool();spectrum_->contrast=contrast->value();spectrum_->brightness=brightness->value()/100.;spectrum_->smoothingFrames=smoothing->value();spectrum_->waterfallStride=speed->value();fixed->setEnabled(!spectrum_->automaticScale);spectrum_->displaySettingsChanged();QSettings settings(settingsFile_,QSettings::IniFormat);spectrum_->saveSettings(settings);};
 connect(mode,&QComboBox::currentIndexChanged,&dialog,[&]{apply();});connect(contrast,&QDoubleSpinBox::valueChanged,&dialog,[&]{apply();});for(auto spin:{brightness,smoothing,speed})connect(spin,&QSpinBox::valueChanged,&dialog,[&]{apply();});fixed->setEnabled(!spectrum_->automaticScale);
 auto buttons=new QDialogButtonBox(QDialogButtonBox::RestoreDefaults|QDialogButtonBox::Close);buttons->button(QDialogButtonBox::RestoreDefaults)->setText("Échelle fixe et réglages par défaut");buttons->button(QDialogButtonBox::Close)->setText("Fermer");connect(buttons->button(QDialogButtonBox::RestoreDefaults),&QPushButton::clicked,&dialog,[&]{mode->setCurrentIndex(0);contrast->setValue(1);brightness->setValue(0);smoothing->setValue(4);speed->setValue(1);apply();});connect(buttons,&QDialogButtonBox::rejected,&dialog,&QDialog::reject);form->addRow(buttons);dialog.exec();
}
